from collections import UserDict
from os import PathLike
from typing import Any, Optional, Union
from urllib.parse import urlencode

import urllib3
from urllib3 import HTTPResponse, Retry
from urllib3.filepost import encode_multipart_formdata
from urllib3.util import make_headers

from thehive4py.__version__ import __version__
from thehive4py.errors import TheHiveError

DEFAULT_RETRY = Retry(
    total=5,
    backoff_factor=1,
    status_forcelist=[500, 502, 503, 504],
    allowed_methods=["GET", "POST", "PUT", "PATCH", "DELETE"],
    raise_on_status=False,
)


RetryValue = Union[Retry, int, None]
VerifyValue = Union[bool, str]


class _SessionJSONEncoder(jsonlib.JSONEncoder):
    """Custom JSON encoder class for TheHive session."""

    def default(self, o: Any):
        if isinstance(o, UserDict):
            return o.data
        return super().default(o)


class TheHiveSession:
    def __init__(
        self,
        url: str,
        apikey: Optional[str] = None,
        username: Optional[str] = None,
        password: Optional[str] = None,
        verify: VerifyValue = True,
        max_retries: RetryValue = DEFAULT_RETRY,
    ):
        self.hive_url = self._sanitize_hive_url(url)
        self.verify = verify
        self.headers: dict = {"User-Agent": f"thehive4py/{__version__}"}

        if username and password:
            self.headers["Authorization"] = make_headers(
                basic_auth=f"{username}:{password}"
            )["authorization"]
        elif apikey:
            self.headers["Authorization"] = f"Bearer {apikey}"
        else:
            raise TheHiveError(
                "Either apikey or the username/password combination must be provided!"
            )

        self.pool_manager = self._build_pool_manager(
            verify=verify, max_retries=max_retries
        )

    def _build_pool_manager(
        self, verify: VerifyValue, max_retries: RetryValue
    ) -> urllib3.PoolManager:
        """Build the urllib3 pool manager used to issue requests."""
        pool_kwargs: dict = {"retries": max_retries}

        if verify is False:
            pool_kwargs["cert_reqs"] = "CERT_NONE"
            urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)
        else:
            pool_kwargs["cert_reqs"] = "CERT_REQUIRED"
            if isinstance(verify, str):
                pool_kwargs["ca_certs"] = verify

        return urllib3.PoolManager(**pool_kwargs)

    def _sanitize_hive_url(self, hive_url: str) -> str:
        """Sanitize the base url for the client."""
        if hive_url.endswith("/"):
            return hive_url[:-1]
        return hive_url

    def _build_multipart_fields(self, data, files) -> list:
        fields: list = []

        if data:
            items = data.items() if isinstance(data, dict) else data
            fields.extend(list(items))

        if files:
            items = files.items() if isinstance(files, dict) else files
            for name, value in items:
                if isinstance(value, (tuple, list)):
                    filename, filedata = value[0], value[1]
                    content_type = value[2] if len(value) > 2 else None
                    if hasattr(filedata, "read"):
                        filedata = filedata.read()
                    if content_type:
                        fields.append((name, (filename, filedata, content_type)))
                    else:
                        fields.append((name, (filename, filedata)))
                else:
                    fields.append((name, value))

        return fields

    def make_request(
        self,
        method: str,
        path: str,
        params=None,
        data=None,
        json=None,
        files=None,
        download_path: Union[str, PathLike, None] = None,
    ) -> Any:
        endpoint_url = f"{self.hive_url}{path}"

        headers = {**self.headers}
        body = None

        if json is not None:
            body = jsonlib.dumps(json, cls=_SessionJSONEncoder).encode("utf-8")
            headers["Content-Type"] = "application/json"
        elif files:
            fields = self._build_multipart_fields(data=data, files=files)
            body, content_type = encode_multipart_formdata(fields)
            headers["Content-Type"] = content_type
        elif data is not None:
            if isinstance(data, bytes):
                body = data
            elif isinstance(data, str):
                body = data.encode("utf-8")
            else:
                body = urlencode(data).encode("utf-8")
                headers["Content-Type"] = "application/x-www-form-urlencoded"

        if params:
            endpoint_url = f"{endpoint_url}?{urlencode(params, doseq=True)}"

        response = self.pool_manager.request(
            method,
            url=endpoint_url,
            body=body,
            headers=headers,
            preload_content=download_path is None,
        )

        return self._process_response(response, download_path=download_path)

    def _process_response(
        self,
        response: HTTPResponse,
        download_path: Union[str, PathLike, None] = None,
    ):
        if response.status < 400:
            if download_path is None:
                return self._process_text_response(response)
            else:
                self._process_stream_response(
                    response=response, download_path=download_path
                )
        else:
            self._process_error_response(response=response)

    def _process_text_response(self, response: HTTPResponse):
        try:
            json_data = jsonlib.loads(response.data)
        except (jsonlib.JSONDecodeError, UnicodeDecodeError, TypeError):
            json_data = None

        if json_data is None:
            return response.data.decode("utf-8", errors="replace")
        return json_data

    def _process_stream_response(
        self, response: HTTPResponse, download_path: Union[str, PathLike]
    ):
        with open(download_path, "wb") as download_fp:
            for chunk in response.stream(4096):
                download_fp.write(chunk)
        response.release_conn()

    def _process_error_response(self, response: HTTPResponse):
        try:
            json_data = jsonlib.loads(response.data)
        except (jsonlib.JSONDecodeError, UnicodeDecodeError, TypeError):
            json_data = None

        if json_data is None:
            error_text = response.data.decode("utf-8", errors="replace")
        else:
            error_text = f"{json_data['type']} - {json_data['message']}"
        raise TheHiveError(message=error_text, response=response)
